questions.explanation:
\begin{center}
			\begin{tikzpicture}[scale=1.5, >=stealth, thick, line join=round, line cap=round]
				% Trục tọa độ
				\draw[->] (-2.5, 0) -- (2.5, 0) node[below] {$x$};
				\draw[->] (0, -0.5) -- (0, 2.5) node[left] {$y$};
				\node[below left] at (0,0) {$O$};

				% Các điểm
				\coordinate (A) at (1.5, 0); % Ví dụ tại t làm x(t) = 1.5
				\coordinate (B) at (0, 1.32); % y(t) = sqrt(4 - 1.5^2) = sqrt(1.75) ~ 1.32

				% Thanh truyền động
				\draw[blue, ultra thick] (A) -- (B) node[midway, above right, black] {$2$};

				% Tọa độ và điểm
				\fill (A) circle (1.5pt) node[below] {$A(x(t); 0)$};
				\fill (B) circle (1.5pt) node[right] {$B(0; y(t))$};

				% Ký hiệu quỹ đạo
				\draw[<->, dashed, red, thin] (-1.732, -0.3) -- (1.732, -0.3) node[midway, below] {$-\sqrt{3} \le x \le \sqrt{3}$};
				\draw[<->, dashed, red, thin] (-0.3, 1) -- (-0.3, 2) node[midway, left] {$1 \le y \le 2$};

				% Vết gốc tọa độ
				\draw (0.15,0) -- (0.15,0.15) -- (0,0.15);
			\end{tikzpicture}
		\end{center}

		\textbf{Phân tích và định hướng giải:}
		\begin{itemize}
			\item Bài toán cho biết độ dài thanh truyền động $AB = 2$. Do $A$ nằm trên $Ox$, $B$ nằm trên $Oy$ nên tam giác $OAB$ vuông tại $O$.
			\item Theo định lý Pythagore: $OA^2 + OB^2 = AB^2 \implies x^2(t) + y^2(t) = 2^2 = 4$.
			\item Từ phương trình liên hệ này, ta biểu diễn được $y(t)$ theo $x(t)$. Vì đề bài cho $y(t) > 0$, ta chỉ lấy căn bậc hai dương.
			\item Sau khi có hàm số $y(t)$ tường minh theo $t$, ta sử dụng tập giá trị của hàm lượng giác $\sin \pi t \in [-1; 1]$ để chặn giá trị của $y(t)$, từ đó tìm được giá trị nhỏ nhất của $y(t)$.
			\item Để tìm số lần điểm $B$ ở vị trí thấp nhất trong 10 giây đầu, ta giải phương trình $y(t) = \min$ trên đoạn $t \in [0; 10]$ và đếm số nghiệm.
		\end{itemize}

		\textbf{Lời giải chi tiết:}

		\textbf{a) Xét mệnh đề a:} \\
		Hàm số $f(t) = \sin \pi t$ là hàm lượng giác cơ bản. Tập giá trị của hàm sin luôn nằm trong đoạn $[-1; 1]$.
		Do đó: $-1 \le \sin \pi t \le 1, \forall t \ge 0$. \\
		$\implies$ \textbf{Mệnh đề a) ĐÚNG.}

		\textbf{b) Xét mệnh đề b:} \\
		Ta có $A(x(t); 0)$ và $B(0; y(t))$. Tam giác $OAB$ vuông tại $O$.
		Áp dụng định lý Pythagore: 
		$$ OA^2 + OB^2 = AB^2 \iff x^2(t) + y^2(t) = 2^2 = 4 $$
		$$ \iff (\sqrt{3}\sin \pi t)^2 + y^2(t) = 4 $$
		$$ \iff 3\sin^2 \pi t + y^2(t) = 4 \implies y^2(t) = 4 - 3\sin^2 \pi t $$
		Vì giả thiết cho $y(t) > 0$, ta có:
		$$ y(t) = \sqrt{4 - 3\sin^2 \pi t} $$
		Biểu thức trong mệnh đề là $\sqrt{1 - 3\sin^2 \pi t}$, điều này là sai (hằng số $4$ bị viết thành $1$). \\
		$\implies$ \textbf{Mệnh đề b) SAI.}

		\textbf{c) Xét mệnh đề c:} \\
		Từ kết quả câu b, ta có: $y(t) = \sqrt{4 - 3\sin^2 \pi t}$. \\
		Vì $0 \le \sin^2 \pi t \le 1$, ta có:
		$$ -3 \le -3\sin^2 \pi t \le 0 $$
		$$ \iff 1 \le 4 - 3\sin^2 \pi t \le 4 $$
		$$ \iff \sqrt{1} \le \sqrt{4 - 3\sin^2 \pi t} \le \sqrt{4} $$
		$$ \iff 1 \le y(t) \le 2 $$
		Vậy tung độ $y(t)$ của điểm $B$ đạt giá trị nhỏ nhất bằng $1$ (khi $\sin^2 \pi t = 1$). \\
		$\implies$ \textbf{Mệnh đề c) ĐÚNG.}

		\textbf{d) Xét mệnh đề d:} \\
		Điểm $B$ ở vị trí có tung độ nhỏ nhất khi $y(t) = 1$.
		$$ \iff \sin^2 \pi t = 1 \iff \sin \pi t = \pm 1 $$
		$$ \iff \pi t = \frac{\pi}{2} + k\pi \iff t = \frac{1}{2} + k \quad (k \in \mathbb{Z}) $$
		Xét trong 10 giây đầu tiên, tức là $0 \le t \le 10$:
		$$ 0 \le \frac{1}{2} + k \le 10 \iff -0,5 \le k \le 9,5 $$
		Vì $k$ là số nguyên nên $k \in \{0; 1; 2; \dots; 9\}$. \\
		Số lượng các giá trị của $k$ là: $9 - 0 + 1 = 10$ (giá trị). \\
		Tương ứng sẽ có 10 thời điểm $t$ để tung độ $B$ đạt giá trị nhỏ nhất trong 10 giây đầu (đó là các thời điểm $t = 0,5; 1,5; 2,5; \dots ; 9,5$). \\
		Mệnh đề khẳng định "có 5 lần" là sai. \\
		$\implies$ \textbf{Mệnh đề d) SAI.}

